{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "Testosterone undecanoate, a lipophilic long-chain ester prodrug, has a mean absolute oral bioavailability of only 6.8 ± 3.3% in humans, supporting low systemic absorption for highly lipophilic ester/lactone structures like orlistat.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester, shows poor and inconsistent oral bioavailability in men, consistent with very low F for lipophilic long-chain ester drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Colesevelam has a bioavailability of <0.04% in humans, illustrating that locally acting, minimally absorbed oral drugs can have negligible systemic F, analogous to orlistat's intended local GI action.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Delmopinol has very low bioavailability after oral administration, supporting the pattern that locally acting oral agents with minimal absorption fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat shows poor oral bioavailability in humans, consistent with low F for lipophilic, poorly soluble drug candidates.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Orlistat is a highly lipophilic, locally acting lipase inhibitor with negligible systemic absorption; analogous long-chain ester prodrugs and minimally absorbed oral drugs all show F well below 20%, so the prediction is low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat is present in the provided records.",
    "Most quantitative analogs are structurally distant; the closest analogs are long-chain ester prodrugs with low but not zero F.",
    "No high-bioavailability analog with a similar beta-lactone/lipase-inhibitor scaffold is available for comparison."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

